#!/usr/bin/env bash
# Generated by mountaya/ai (scripts/apply.mjs). Edit .agents/manifest.json instead.
#
# What every script under scripts/ needs before it starts: how it prints, how it
# stops, and how it checks the tools it will run. A script checks every CLI it runs
# before it has any effect, and `node ../ai/scripts/apply.mjs --check` fails one that
# does not.
#
# Sourced, never executed: . "$(dirname "$0")/lib/common.sh"
# bash 3.2, because macOS still ships it as /bin/bash, and safe under `set -euo pipefail`.

if [ -t 1 ]; then
  PF_RESET=$'\033[0m'
  PF_BOLD=$'\033[1m'
  PF_RED=$'\033[31m'
  PF_GREEN=$'\033[32m'
  PF_YELLOW=$'\033[33m'
  PF_DIM=$'\033[2m'
else
  PF_RESET=""; PF_BOLD=""; PF_RED=""; PF_GREEN=""; PF_YELLOW=""; PF_DIM=""
fi

info() { echo "${PF_DIM}·${PF_RESET} $*"; }
ok()   { echo "${PF_GREEN}✓${PF_RESET} $*"; }
warn() { echo "${PF_YELLOW}!${PF_RESET} $*" >&2; }

# die <message> [<next-step>...]: what went wrong, then each concrete thing to do about
# it under "Next:". It exits the current shell, so call it from the main shell of a
# script, never from inside a pipeline.
die() {
  local message="$1" step
  shift
  echo "" >&2
  echo "${PF_RED}${PF_BOLD}✗ $message${PF_RESET}" >&2
  if [ "$#" -gt 0 ]; then
    echo "" >&2
    echo "${PF_BOLD}Next:${PF_RESET}" >&2
    for step in "$@"; do
      echo "  $step" >&2
    done
  fi
  echo "" >&2
  exit 1
}

has_cmd() { command -v "$1" >/dev/null 2>&1; }

# require_cmd <command> <install hint>: a tool mise.toml does not pin, such as what ships
# with the operating system. A pinned tool goes through require_pinned.
require_cmd() {
  has_cmd "$1" && return 0
  die "'$1' is not on PATH." "$2"
}

# require_pinned <command> [<then>]: a tool mise.toml pins. Absent from PATH means
# `mise install` has not run since the pin was added, or this shell is not one mise
# activates, and the hint covers both. <then> is a step the tool needs once it is
# installed, such as a login.
require_pinned() {
  has_cmd "$1" && return 0
  die "'$1' is not on PATH. mise.toml pins it." \
    "mise install${2:+    # then: $2}" \
    "Still missing? This shell does not activate mise: add eval \"\$(mise activate zsh)\" to your" \
    "shell profile, or run the command under \`mise exec --\`. No mise at all: sh .agents/setup"
}

# The script itself, as an absolute path, read at source time, so a script sources this before it changes directory.
_COMMON_SCRIPT="$(cd "$(dirname "$0")" 2>/dev/null && pwd)/$(basename "$0")"

# answer_help "$@": with -h or --help first, prints the script's USAGE-START block, or
# else its leading comment, and exits 0. It runs before the tool checks, so asking how a
# script works never needs its tools.
answer_help() {
  case "${1:-}" in
    -h | --help) ;;
    *) return 0 ;;
  esac
  if grep -q '^# USAGE-START' "$_COMMON_SCRIPT"; then
    sed -n '/^# USAGE-START/,/^# USAGE-END/p' "$_COMMON_SCRIPT" | sed '1d;$d' | sed 's/^# \{0,1\}//'
  else
    sed -n '2,/^[^#]/p' "$_COMMON_SCRIPT" | sed -n 's/^# \{0,1\}//p'
  fi
  exit 0
}
